e122d819	بايو	[{"back": "Oxaloacetate, pyruvate, α-ketoglutarate, fumarate, succinyl CoA, acetyl CoA, and acetoacetate", "front": "What are the seven intermediates into which amino acid catabolism converges?"}, {"back": "Nonessential amino acids", "front": "Which amino acids are synthesized from intermediates of metabolism or from essential amino acids (cysteine and tyrosine)?"}, {"back": "Essential amino acids", "front": "Which amino acids cannot be synthesized in sufficient amounts and must be obtained from the diet?"}, {"back": "Amino acids whose catabolism yields pyruvate or one of the citric acid cycle intermediates", "front": "Which amino acids are termed glucogenic?"}, {"back": "In the liver and kidney", "front": "Where can glucogenic amino acids give rise to net glucose formation?"}, {"back": "Amino acids whose catabolism yields acetoacetate or one of its precursors (acetyl CoA or acetoacetyl CoA)", "front": "Which amino acids are termed ketogenic?"}, {"back": "Acetoacetate, 3-hydroxybutyrate, and acetone", "front": "Name the three ketone bodies."}, {"back": "Leucine and lysine", "front": "Which are the only exclusively ketogenic amino acids found in proteins?"}, {"back": "Their carbon skeletons are not substrates for gluconeogenesis", "front": "Why can leucine and lysine not form net glucose?"}, {"back": "Tyrosine", "front": "Which amino acid is both glucogenic and ketogenic among the nonessential amino acids?"}, {"back": "Isoleucine, phenylalanine, and tryptophan", "front": "Which essential amino acids are both glucogenic and ketogenic?"}, {"back": "Six (leucine, isoleucine, lysine, tryptophan, phenylalanine, and tyrosine)", "front": "How many ketogenic amino acids are there in total?"}, {"back": "Histidine, methionine, threonine, and valine", "front": "Which essential amino acids are purely glucogenic?"}, {"back": "Alanine", "front": "Which amino acid is the major gluconeogenic amino acid?"}, {"back": "Asparaginase", "front": "Which enzyme hydrolyzes aspa